mongodb:createCollection.mongodb:options:
{
        "validator": {"$jsonSchema": {
          "bsonType": "object",
          "required": ["_id", "nombre", "hectareas", "condiciones_edaficas", "sistema_riego"],
          "properties": {
            "_id": {"bsonType": "string", "description": "ID alfanumérico único de la parcela"},
            "nombre": {"bsonType": "string", "description": "Nombre de la parcela"},
            "fundo": {"bsonType": "string"},
            "hectareas": {"bsonType": ["double", "int", "decimal"], "minimum": 0.1},
            "condiciones_edaficas": {
              "bsonType": "object",
              "required": ["textura", "ph_promedio"],
              "properties": {
                "textura": {"bsonType": "string"},
                "ph_promedio": {"bsonType": ["double", "int", "decimal"]}
              }
            },
            "sistema_riego": {
              "bsonType": "object",
              "required": ["tipo", "caudal_lph"],
              "properties": {
                "tipo": {"bsonType": "string"},
                "caudal_lph": {"bsonType": ["double", "int", "decimal"]}
              }
            }
          }
        }},
        "validationLevel": "strict",
        "validationAction": "error"
      }
